// ALPHA IA: LA CARA DEL PANEL (5-oct-2026).
//
// QUÉ SE PEDÍA. El dueño: "que la interfaz se vea más ALPHA IA, con el logo,
// bonita, con animaciones decentes, confiable y minimalista con toques
// futuristas". Y: "que las imágenes se vean: las fichas, que se deslicen como
// en Instagram, y la foto que manda el cliente".
//
// ESTE ARCHIVO ES IGUAL EN LAS TRES TIENDAS Y EN EL PANEL CENTRAL (src/alpha.js).
// Aquí vive todo lo que se ve igual en los dos paneles: el logo, el estilo,
// el script de la página y cómo se pintan las fotos y las fichas. Un cambio
// de diseño se hace aquí y se pega en las cuatro carpetas.
//
// Sin librerías ni nada de fuera: el logo va dentro de este archivo y el
// panel lo sirve él mismo (/panel/logo.png en las tiendas, /logo.png en el
// central). Carga rápido en el teléfono y no depende de otro servidor.
//
// OSCURO POR DEFECTO, CLARO SI SE PIDE (6-oct-2026, dueño: "poder cambiarle
// el color de blanco o negro"). El interruptor de sol y luna (en la barra y
// en la pantalla de entrada) cambia de tema y cada navegador lo recuerda. El
// logo tiene "ALPHA" en blanco plateado y sobre blanco desaparecería: en el
// tema claro va sobre su placa oscura.

import { iconoSuelto } from "./iconos.js";

/* ── El logo ─────────────────────────────────────────────────────────
   LOGO: el completo (la A, "ALPHA IA" y "Soluciones que impulsan"), para la
   pantalla de entrada. ISOTIPO: solo la A, para la barra de arriba. Para
   cambiarlo: un PNG con fondo transparente, en base64, en su constante. */

export const LOGO_PNG = "";
export const ISOTIPO_PNG = "";

// El ícono de la app instalada (7-oct-2026): la A sobre fondo oscuro,
// cuadrado, con margen para que Android lo recorte en círculo sin comerse
// la letra.
export const APP_192_PNG = "";
export const APP_512_PNG = "";

const IMAGENES = { "logo.png": LOGO_PNG, "isotipo.png": ISOTIPO_PNG, "app-192.png": APP_192_PNG, "app-512.png": APP_512_PNG };

// La respuesta para /panel/logo.png o /logo.png (null si no es una de ellas).
// Va sin sesión: la pantalla de entrada la necesita.
export function imagenDeAlpha(nombre) {
  const base64 = IMAGENES[nombre];
  if (!base64) return null;
  const bytes = Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
  return new Response(bytes, {
    headers: {
      "content-type": "image/png",
      "cache-control": "public, max-age=86400",
      "x-content-type-options": "nosniff",
    },
  });
}

function esc(texto) {
  return String(texto ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// La marca de la barra de arriba: la A, "ALPHA IA" y, al lado, de quién es
// el panel (la tienda, o "Panel central").
export function marcaAlpha(prefijo, detalle = "") {
  return `<a class="alpha" href="${esc(prefijo || "/")}" aria-label="ALPHA IA"><img src="${esc(prefijo)}/isotipo.png?v=1" alt="" width="40" height="28"><span class="alpha-nombre">ALPHA <span class="ia">IA</span></span>${detalle ? `<span class="alpha-de">${esc(detalle)}</span>` : ""}</a>${BOTON_TEMA}${SCRIPT_TEMA}`;
}

// EL TEMA CLARO / OSCURO (6-oct-2026). El botón y el script van junto a la
// marca (barra de arriba) y en la pantalla de entrada: así ningún panel
// tiene que tocarse para tenerlo. El script corre ahí mismo, antes de que
// se pinte el resto de la página, para que no parpadee de oscuro a claro.
// Lo elegido se guarda en ESTE navegador (cada persona elige el suyo); si
// el navegador no deja guardar, se queda en oscuro y el botón sigue
// funcionando mientras la página está abierta.
// El interruptor: un riel con el sol y la luna y una bolita que se desliza
// (7-oct-2026: sin emojis, que cambian de dibujo según el teléfono).
export function botonDeTema() {
  return `<button type="button" class="tema" data-tema-boton title="Cambiar entre claro y oscuro" aria-label="Cambiar entre claro y oscuro"><span class="a-claro">${iconoSuelto("sol")}</span><span class="a-oscuro">${iconoSuelto("luna")}</span></button>`;
}
const BOTON_TEMA = botonDeTema();

// Al cambiar de tema, el nuevo color se abre en círculo desde el botón
// (View Transitions). Donde el navegador no sabe, cambia sin animación.
export const SCRIPT_TEMA = `<script>(function(){var d=document.documentElement;
if(!window.__alphaTema){window.__alphaTema=1;
try{if(localStorage.getItem("alpha-tema")==="claro")d.setAttribute("data-tema","claro")}catch(e){}
document.addEventListener("click",function(e){var b=e.target.closest&&e.target.closest("[data-tema-boton]");if(!b)return;
var claro=d.getAttribute("data-tema")!=="claro";
function poner(){if(claro)d.setAttribute("data-tema","claro");else d.removeAttribute("data-tema");
var m=document.querySelector('meta[name="theme-color"]');if(m)m.setAttribute("content",claro?"#f3f5fa":"#05070d")}
try{localStorage.setItem("alpha-tema",claro?"claro":"oscuro")}catch(e){}
var quieto=window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;
if(!document.startViewTransition||quieto)return poner();
var r=b.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,radio=Math.hypot(Math.max(x,innerWidth-x),Math.max(y,innerHeight-y));
d.classList.add("cambiando-tema");
var t=document.startViewTransition(poner);
t.ready.then(function(){d.animate({clipPath:["circle(0px at "+x+"px "+y+"px)","circle("+radio+"px at "+x+"px "+y+"px)"]},{duration:650,easing:"cubic-bezier(.16,1,.3,1)",pseudoElement:"::view-transition-new(root)"})}).catch(function(){});
t.finished.then(function(){d.classList.remove("cambiando-tema")},function(){d.classList.remove("cambiando-tema")});
});}
try{if(d.getAttribute("data-tema")==="claro"){var m=document.querySelector('meta[name="theme-color"]');if(m)m.setAttribute("content","#f3f5fa")}}catch(e){}
})();</script>`;

// La pantalla de entrada: el logo grande y la clave.
export function cajaDeEntrada(prefijo, { accion, texto = "", error = "", detalle = "" } = {}) {
  return `<div class="tema-flotante">${BOTON_TEMA}</div>${SCRIPT_TEMA}<div class="entrada"><div class="entrada-aurora" aria-hidden="true"><i></i><i></i><i></i></div><form class="entrada-caja" method="post" action="${esc(accion)}">
<img class="entrada-logo" src="${esc(prefijo)}/logo.png?v=1" alt="ALPHA IA · Soluciones que impulsan" width="317" height="184">
${detalle ? `<div class="entrada-de">${esc(detalle)}</div>` : ""}
<p class="suave">${esc(texto)}</p>${error ? `<p class="entrada-error">${iconoSuelto("alerta", { clase: "chico" })}${esc(error)}</p>` : ""}
<label class="entrada-clave">${iconoSuelto("candado")}<input type="password" name="clave" autocomplete="current-password" placeholder="Clave" aria-label="Clave" autofocus></label>
<input type="hidden" name="pregunta_sesion" value="1"><label class="entrada-recordar"><span><b>¿Dejar la sesión abierta?</b><small data-si="En este equipo no te volverá a pedir la clave." data-no="Se cerrará al cerrar el navegador.">En este equipo no te volverá a pedir la clave.</small></span><input type="checkbox" name="recordar" value="si" checked role="switch" aria-label="Dejar la sesión abierta en este equipo" onchange="var t=this.parentNode.querySelector('small');t.textContent=t.getAttribute(this.checked?'data-si':'data-no')"></label>
<button class="principal">Entrar${iconoSuelto("adelante", { clase: "chico" })}</button></form></div>`;
}

/* ── Fotos y fichas de un mensaje ────────────────────────────────────
   Lo que se guarda junto al mensaje (columna "adjuntos" de la tabla
   mensajes, en JSON):
     { fotos: ["https://…"], historia: true, fichas: [{ titulo, precio, imagen }] }
   · fotos: la que mandó el cliente (o la historia a la que respondió).
   · fichas: el carrusel que mandó el bot, tal cual lo vio el cliente.
   Solo enlaces https: lo demás no se guarda ni se pinta. */

const MAX_FICHAS = 10;

function enlaceBueno(url) {
  const t = String(url || "").trim();
  return t.length <= 2000 && /^https:\/\/[^\s"'<>\\]+$/i.test(t) ? t : "";
}

export function adjuntosLimpios(a) {
  if (!a || typeof a !== "object") return null;
  const fotos = (Array.isArray(a.fotos) ? a.fotos : [a.foto]).map(enlaceBueno).filter(Boolean).slice(0, 4);
  const fichas = (Array.isArray(a.fichas) ? a.fichas : [])
    .slice(0, MAX_FICHAS)
    .map((p) => ({
      titulo: String(p?.titulo || "").slice(0, 120),
      precio: String(p?.precio ?? "").slice(0, 40),
      imagen: enlaceBueno(p?.imagen),
    }))
    .filter((f) => f.titulo || f.imagen);
  if (!fotos.length && !fichas.length) return null;
  const limpio = {};
  if (fotos.length) limpio.fotos = fotos;
  if (fotos.length && a.historia) limpio.historia = true;
  if (fichas.length) limpio.fichas = fichas;
  return limpio;
}

// De la columna de la base (texto JSON) al objeto, limpio.
export function leerAdjuntos(valor) {
  if (!valor) return null;
  if (typeof valor === "object") return adjuntosLimpios(valor);
  try {
    return adjuntosLimpios(JSON.parse(valor));
  } catch {
    return null;
  }
}

// Las imágenes de un mensaje, en una lista (para "En vivo": miniaturas).
export function imagenesDeAdjuntos(a) {
  const limpio = adjuntosLimpios(a);
  if (!limpio) return [];
  return [...(limpio.fotos || []), ...(limpio.fichas || []).map((f) => f.imagen)].filter(Boolean).slice(0, 6);
}

// El texto que se guarda cuando el mensaje es solo imágenes.
export function textoDeAdjuntos(a, de = "cliente") {
  const limpio = adjuntosLimpios(a);
  if (!limpio) return "";
  if (limpio.fichas) return `📷 Fichas: ${limpio.fichas.map((f) => f.titulo).join(" · ")}`;
  if (limpio.historia) return "(respondió a una historia)";
  return de === "cliente" ? "(mandó una foto)" : "(foto)";
}

// El texto de la burbuja cuando ya se ven las imágenes: sin repetir
// "(mandó una foto)" ni la lista de fichas escrita.
export function textoVisible(texto, a) {
  const limpio = adjuntosLimpios(a);
  let t = String(texto || "");
  if (!limpio) return t;
  if (limpio.fichas) t = t.replace(/^📷 Fichas[^\n]*/u, "");
  if (limpio.fotos) t = t.replace(/\((mandó una foto|respondió a una historia)\)/g, "");
  return t.trim();
}

function imagen(url, alt, clase) {
  return `<a class="${clase}" href="${esc(url)}" target="_blank" rel="noopener noreferrer" data-ampliar><img src="${esc(url)}" alt="${esc(alt)}" loading="lazy" decoding="async" referrerpolicy="no-referrer"></a>`;
}

// Las fotos y el carrusel, en HTML. Todo pasa por adjuntosLimpios y esc.
export function htmlDeAdjuntos(a) {
  const limpio = adjuntosLimpios(a);
  if (!limpio) return "";
  let html = "";
  if (limpio.historia) html += `<span class="historia">${iconoSuelto("deshacer", { clase: "chico" })} Respondió a una historia</span>`;
  for (const url of limpio.fotos || []) html += imagen(url, "Foto que mandó el cliente", "foto");
  const fichas = limpio.fichas || [];
  if (fichas.length) {
    const flechas =
      fichas.length > 1
        ? '<button type="button" class="carrusel-flecha izq" data-mover="-1" aria-label="Anterior">‹</button><button type="button" class="carrusel-flecha der" data-mover="1" aria-label="Siguiente">›</button>'
        : "";
    html += `<div class="carrusel">${flechas}<div class="carrusel-pista">${fichas
      .map(
        (f) =>
          `<div class="ficha">${f.imagen ? imagen(f.imagen, f.titulo, "ficha-img") : `<div class="ficha-img vacia">${iconoSuelto("foto")}</div>`}<div class="ficha-pie"><b>${esc(f.titulo)}</b>${f.precio ? `<span class="precio">${esc(f.precio)}</span>` : ""}</div></div>`
      )
      .join("")}</div>${fichas.length > 1 ? `<div class="carrusel-cuenta">${fichas.length} fichas · desliza →</div>` : ""}</div>`;
  }
  return html;
}

/* ── Números, gráficos y el calendario (los dos paneles) ──────────── */

export function kpi(valor, etiqueta, { clase = "", titulo = "" } = {}) {
  return `<div class="kpi" title="${esc(titulo)}"><div class="v ${clase}">${esc(valor)}</div><div class="e">${esc(etiqueta)}</div></div>`;
}

// Un gráfico de barras de UNA serie (sin leyenda: el título la nombra),
// con el valor de cada día al pasar el dedo o el ratón.
export function barras(titulo, dias, campo) {
  const max = Math.max(1, ...dias.map((d) => Number(d[campo]) || 0));
  const total = dias.reduce((s, d) => s + (Number(d[campo]) || 0), 0);
  const cuerpo = dias
    .map((d) => {
      const v = Number(d[campo]) || 0;
      return `<div class="barra"><i style="height:${Math.round((v / max) * 100)}%"></i><span class="tip">${esc(d.dia.slice(5))}: ${v}</span></div>`;
    })
    .join("");
  return `<div class="tarjeta grafico"><div class="nombre">${esc(titulo)}<span class="suave">${total} en total · máximo ${max === 1 && !total ? 0 : max} en un día</span></div>
<div class="barras" role="img" aria-label="${esc(titulo)} por día">${cuerpo}</div>
<div class="ejes"><span>${esc(dias[0]?.dia.slice(5) || "")}</span><span>${esc(dias.at(-1)?.dia.slice(5) || "")}</span></div></div>`;
}

// "2026-10-02" → "2 oct" (la fecha tal cual, sin moverla de día).
export function fechaCorta(dia) {
  const ms = Date.parse(`${dia}T12:00:00Z`);
  if (!Number.isFinite(ms)) return String(dia || "");
  return new Date(ms).toLocaleDateString("es-VE", { day: "numeric", month: "short", timeZone: "UTC" }).replace(/\.$/, "");
}

// EL CALENDARIO (5-oct-2026). El dueño: "un calendario de elección, junto a
// las sugerencias de 7, 14, 30 y 90 días, que funcione bien: pongo 30 y 7 y
// dice lo mismo". Decía lo mismo porque solo hay datos desde hace unos días:
// ahora se ve el rango exacto que se está mirando y desde cuándo hay datos.
//   periodo: lo que se pidió ({ aMedida, dias } o { aMedida, desde, hasta })
//   rango: lo que la tienda de verdad contó ({ desde, hasta, dias })
export function selectorDePeriodo({ periodo = {}, rango = null, primerDato = "", hoy = "", avisos = [] } = {}) {
  const atajos = [7, 14, 30, 90]
    .map((n) => `<a class="${!periodo.aMedida && periodo.dias === n ? "activa" : ""}" href="?dias=${n}">${n} días</a>`)
    .join("");
  const desde = rango?.desde || periodo.desde || "";
  const hasta = rango?.hasta || periodo.hasta || hoy;
  const viendo = rango
    ? `${periodo.aMedida ? "Del" : `Últimos ${rango.dias} días · del`} ${fechaCorta(rango.desde)} al ${fechaCorta(rango.hasta)}${periodo.aMedida ? ` · ${rango.dias} ${rango.dias === 1 ? "día" : "días"}` : ""}`
    : "";
  const corto = primerDato && desde && primerDato > desde;
  return `<div class="periodo tarjeta">
<div class="atajos">${atajos}</div>
<form method="get" class="calendario"><label>Desde<input type="date" name="desde" value="${esc(desde)}"${hoy ? ` max="${esc(hoy)}"` : ""}></label><label>Hasta<input type="date" name="hasta" value="${esc(hasta)}"${hoy ? ` max="${esc(hoy)}"` : ""}></label><button class="principal">Ver</button></form>
<div class="suave periodo-texto">${viendo ? `${iconoSuelto("calendario", { clase: "chico" })} ${esc(viendo)}` : ""}${primerDato ? ` · hay datos desde el <b>${esc(fechaCorta(primerDato))}</b>` : ""}${corto ? ". Antes de esa fecha no hay nada guardado: por eso un período más largo da los mismos números." : ""}</div>
${avisos.map((a) => `<div class="aviso">${iconoSuelto("alerta", { clase: "chico" })} ${esc(a)}</div>`).join("")}</div>`;
}

// UN CSV QUE ABRE BIEN EN EXCEL EN ESPAÑOL: con BOM (para las tildes) y
// punto y coma (el separador de Excel cuando la coma es el decimal).
export function aCsv(encabezados, filas) {
  const celda = (v) => {
    // Un texto que empieza por = + - @ Excel lo toma como fórmula: un cliente
    // podría escribir una. Con el apóstrofo delante queda como texto.
    const t = typeof v === "string" && /^[=+\-@\t\r]/.test(v) ? `'${v}` : String(v ?? "");
    return /[";\n\r]/.test(t) ? `"${t.replace(/"/g, '""')}"` : t;
  };
  return "\uFEFF" + [encabezados, ...filas].map((f) => f.map(celda).join(";")).join("\r\n") + "\r\n";
}

export function respuestaCsv(nombre, contenido) {
  return new Response(contenido, {
    headers: {
      "content-type": "text/csv; charset=utf-8",
      "content-disposition": `attachment; filename="${String(nombre).replace(/[^\w.-]/g, "_")}"`,
      "cache-control": "no-store",
    },
  });
}

